	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Order_
	 */
		public Order_ createOrder_( CreateOrder_Command command ) {

		Order_ entity = new Order_();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setOrder_Id( command.getOrder_Id() );
            entity.setOrderNumber( command.getOrderNumber() );
            entity.setQuantity( command.getQuantity() );
            entity.setLimitPrice( command.getLimitPrice() );
            entity.setOrderType( command.getOrderType() );
            entity.setSide( command.getSide() );
            entity.setPriceType( command.getPriceType() );
            entity.setTimeInForce( command.getTimeInForce() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Order_ {0} ", entity.toString() );

		return entity;
	}

